package com.volna.inventory_service.controller;import com.volna.inventory_service.dto.purchaseorder.CreatePurchaseOrderRequest;import com.volna.inventory_service.dto.purchaseorder.PurchaseOrderResponse;import com.volna.inventory_service.security.AuthenticatedUser;import com.volna.inventory_service.service.PurchaseOrderService;import jakarta.validation.Valid;import org.springframework.http.*;import org.springframework.security.core.annotation.AuthenticationPrincipal;import org.springframework.web.bind.annotation.*;@RestController @RequestMapping("/api/v1/inventory/purchase-orders") public class PurchaseOrderController{private final PurchaseOrderService s;public PurchaseOrderController(PurchaseOrderService s){this.s=s;}@PostMapping public ResponseEntity<PurchaseOrderResponse> create(@AuthenticationPrincipal AuthenticatedUser u,@Valid @RequestBody CreatePurchaseOrderRequest q){return ResponseEntity.status(HttpStatus.CREATED).body(s.create(u.authUserId(),q));}}
